refentry.refsect1:
&reftitle.description;
public boolnullYaf_Response_Abstract::setRedirect stringurl
Redireciona o cliente para outra URL (envia um cabeçalho Location).

  &reftitle.parameters;


    url

A URL para a qual redirecionar.

  &reftitle.examples;

   Exemplo de Yaf_Response_Abstract::setRedirect


<?php
class AccountController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        if (!Yaf_Session::getInstance()->has("login")) {
            /* envia um cabeçalho Location apontando para a página de login */
            $this->getResponse()->setRedirect("/account/login");
            return false; // nada a renderizar aqui
        }
    }
}
?>
